import csv
import json
from pathlib import Path

ROOT = Path(__file__).parent
EVAL = ROOT / 'evaluation' / 'gift-cards-batch-100'
metrics = json.loads((EVAL / 'metrics.json').read_text(encoding='utf-8'))
with (EVAL / 'scored_reviews.csv').open(encoding='utf-8-sig', newline='') as f:
    reviews = list(csv.DictReader(f))
assert len(reviews) == metrics['n'] == 100
assert sum(r['correct'] == 'True' for r in reviews) == metrics['correct']
assert sum(r['correct'] == 'False' for r in reviews) == metrics['incorrect']

payload = json.dumps({'metrics': metrics, 'reviews': reviews}, ensure_ascii=False).replace('</', '<\\/')
html = r'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>Astra sentiment evaluation dashboard</title>
<style>
:root{--bg:#f4f6f2;--surface:#fff;--surface-2:#edf2ec;--ink:#17221b;--muted:#657168;--line:#d7dfd7;--accent:#277653;--accent-2:#b36a32;--danger:#a8443d;--shadow:0 10px 28px #1b33220d}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.45 ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}main{max-width:1180px;margin:auto;padding:34px 24px 60px}.kicker{color:var(--accent);font-size:11px;font-weight:800;letter-spacing:.14em;text-transform:uppercase}h1{font-size:clamp(30px,4vw,50px);line-height:1.02;letter-spacing:-.055em;margin:8px 0 12px}h2{font-size:19px;letter-spacing:-.02em;margin:0 0 4px}.lede{max-width:740px;color:var(--muted);margin:0 0 25px}.topline{display:flex;justify-content:space-between;align-items:end;gap:20px}.context{font-size:12px;color:var(--muted);text-align:right;max-width:300px}.cards{display:grid;grid-template-columns:1.3fr repeat(3,1fr);gap:1px;background:var(--line);border:1px solid var(--line);box-shadow:var(--shadow);margin:24px 0}.card{background:var(--surface);padding:20px}.card:first-child{background:var(--accent);color:#fff}.value{display:block;font-size:32px;font-weight:800;letter-spacing:-.05em}.label{font-size:12px;color:var(--muted)}.card:first-child .label{color:#d9ede1}.grid{display:grid;grid-template-columns:1.05fr .95fr;gap:16px;margin-top:16px}.panel{background:var(--surface);border:1px solid var(--line);box-shadow:var(--shadow);padding:20px}.sub{color:var(--muted);font-size:12px;margin:0 0 18px}.barrow{display:grid;grid-template-columns:94px 1fr 74px;gap:10px;align-items:center;margin:14px 0}.bar{height:25px;background:var(--surface-2);position:relative}.fill{height:100%;background:var(--accent)}.fill.warn{background:var(--accent-2)}.bar b{position:absolute;left:9px;top:3px;color:white;font-size:12px;text-shadow:0 1px 2px #1c3f2b}.right{text-align:right;color:var(--muted);font-size:12px;font-variant-numeric:tabular-nums}.matrix{display:grid;grid-template-columns:1fr 1fr;gap:9px}.matrix div{padding:17px;background:var(--surface-2)}.matrix strong{font-size:28px;display:block;letter-spacing:-.04em}.matrix small{color:var(--muted)}.matrix .bad{background:#faece9}.matrix .good{background:#e5f2e8}.toolbar{display:flex;gap:9px;flex-wrap:wrap;margin:16px 0}button,select,input{font:inherit;border:1px solid var(--line);background:var(--surface);color:var(--ink);padding:9px 11px;border-radius:5px}button{cursor:pointer}button.active{background:var(--ink);color:#fff;border-color:var(--ink)}input{min-width:220px;flex:1}table{width:100%;border-collapse:collapse}th,td{border-top:1px solid var(--line);padding:11px 7px;text-align:left;vertical-align:top}th{font-size:10px;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);white-space:nowrap}.review-title{font-weight:700;max-width:230px}.review-text{color:var(--muted);max-width:460px;white-space:pre-wrap}.pill{display:inline-block;border-radius:99px;padding:3px 7px;font-size:10px;font-weight:800;letter-spacing:.04em;white-space:nowrap}.pos{color:#236746;background:#e4f2e9}.neg{color:#963c36;background:#f9e8e5}.match{color:#236746}.miss{color:#963c36}.count{color:var(--muted);font-size:12px;margin-left:auto}details{margin-top:16px}summary{cursor:pointer;color:var(--accent);font-weight:700}footer{color:var(--muted);font-size:11px;margin-top:22px}.hidden{display:none!important}@media(max-width:800px){main{padding:25px 15px}.topline{display:block}.context{text-align:left;margin-top:12px}.cards{grid-template-columns:1fr 1fr}.card:first-child{grid-column:span 2}.grid{grid-template-columns:1fr}.review-text{max-width:250px}}@media(max-width:560px){.cards{grid-template-columns:1fr}.card:first-child{grid-column:auto}.review-text{max-width:160px}th:nth-child(3),td:nth-child(3){display:none}}
</style>
</head>
<body><main>
<div class="topline"><div><div class="kicker">Astra · Amazon Gift Cards · batch 01</div><h1>Sentiment evaluation, without the spin.</h1><p class="lede">A blinded read of the first 100 reviews. Astra saw title and text only; the rating was converted to a reference label after predictions were locked.</p></div><div class="context">Reference rule<br><strong>4–5★ = POSITIVE</strong> · <strong>1–3★ = NEGATIVE</strong></div></div>
<div class="cards"><div class="card"><span class="value" id="accuracy">—</span><span class="label">overall accuracy</span></div><div class="card"><span class="value" id="balanced">—</span><span class="label">balanced accuracy</span></div><div class="card"><span class="value" id="macro">—</span><span class="label">macro F1</span></div><div class="card"><span class="value" id="baseline">—</span><span class="label">always-positive baseline</span></div></div>
<div class="grid"><section class="panel"><h2>Where it gets answers right</h2><p class="sub">Accuracy within each source rating. Sample size is shown at right.</p><div id="rating-bars"></div></section><section class="panel"><h2>What the mistakes look like</h2><p class="sub">Reference labels in rows; Astra predictions in columns.</p><div class="matrix"><div class="good"><strong id="pp">—</strong><small>positive → positive</small></div><div class="bad"><strong id="pn">—</strong><small>positive → negative</small></div><div class="bad"><strong id="np">—</strong><small>negative → positive</small></div><div class="good"><strong id="nn">—</strong><small>negative → negative</small></div></div><details><summary>How to read this</summary><p class="sub">The diagonal is correct against the rating proxy. Off-diagonal cells are the two disagreements. Because only 7 of 100 reviews are reference-negative, balanced accuracy is more informative than raw accuracy alone.</p></details></section></div>
<section class="panel" style="margin-top:16px"><div style="display:flex;gap:12px;align-items:baseline;flex-wrap:wrap"><div><h2>Review-level audit</h2><p class="sub" style="margin-bottom:0">Every row is available below so the headline can be checked against the evidence.</p></div><span class="count" id="count">100 reviews</span></div><div class="toolbar"><button class="active" data-filter="all">All</button><button data-filter="errors">Errors only</button><button data-filter="positive">Reference positive</button><button data-filter="negative">Reference negative</button><input id="search" placeholder="Search title or review text…" aria-label="Search reviews"><select id="rating"><option value="all">All ratings</option><option>1</option><option>2</option><option>3</option><option>4</option><option>5</option></select></div><div style="overflow:auto"><table><thead><tr><th>Row</th><th>Review</th><th>Rating</th><th>Reference</th><th>Astra</th><th>Result</th></tr></thead><tbody id="rows"></tbody></table></div></section>
<footer>Generated from the locked first-batch predictions and post-hoc rating comparison. Ratings are a proxy target, not gold sentiment labels. Offline artifact: no external scripts, fonts, APIs, or network requests.</footer>
</main><script>
const DATA = __PAYLOAD__;
const m=DATA.metrics, reviews=DATA.reviews; const pct=x=>(x*100).toFixed(1)+'%';
document.querySelector('#accuracy').textContent=pct(m.accuracy); document.querySelector('#balanced').textContent=pct(m.balanced_accuracy); document.querySelector('#macro').textContent=pct(m.macro_f1); document.querySelector('#baseline').textContent=pct(m.always_positive_accuracy);
const cm=m.confusion_matrix; for(const [id,val] of [['pp',cm.POSITIVE.POSITIVE],['pn',cm.POSITIVE.NEGATIVE],['np',cm.NEGATIVE.POSITIVE],['nn',cm.NEGATIVE.NEGATIVE]]) document.querySelector('#'+id).textContent=val;
const rb=document.querySelector('#rating-bars'); for(const [star,v] of Object.entries(m.rating_breakdown)){const a=v.correct/v.n; rb.insertAdjacentHTML('beforeend',`<div class="barrow"><div>${star} star</div><div class="bar"><div class="fill ${star==='3'?'warn':''}" style="width:${a*100}%"></div><b>${pct(a)}</b></div><div class="right">${v.correct}/${v.n}</div></div>`)}
let filter='all'; const buttons=[...document.querySelectorAll('[data-filter]')]; buttons.forEach(b=>b.onclick=()=>{filter=b.dataset.filter;buttons.forEach(x=>x.classList.toggle('active',x===b));render()}); document.querySelector('#search').oninput=render; document.querySelector('#rating').onchange=render;
function render(){const q=document.querySelector('#search').value.toLowerCase(), rating=document.querySelector('#rating').value; const out=reviews.filter(r=>(filter==='all'||(filter==='errors'&&r.correct==='False')||(filter===r.reference.toLowerCase()))&&(rating==='all'||r.rating===rating)&&(!q||(r.title+' '+r.text).toLowerCase().includes(q))); document.querySelector('#count').textContent=out.length+' review'+(out.length===1?'':'s'); document.querySelector('#rows').innerHTML=out.map(r=>`<tr><td>#${r.id}</td><td><div class="review-title">${esc(r.title)}</div><div class="review-text">${esc(r.text)}</div></td><td>${r.rating}★</td><td><span class="pill ${r.reference==='POSITIVE'?'pos':'neg'}">${r.reference}</span></td><td><span class="pill ${r.prediction==='POSITIVE'?'pos':'neg'}">${r.prediction}</span></td><td class="${r.correct==='True'?'match':'miss'}">${r.correct==='True'?'✓ correct':'✕ mismatch'}</td></tr>`).join('')||'<tr><td colspan="6">No reviews match these filters.</td></tr>'}
function esc(s){return s.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;')}; render();
</script></body></html>'''.replace('__PAYLOAD__', payload)
out = ROOT / 'evaluation' / 'gift-cards-batch-100' / 'dashboard.html'
out.write_text(html, encoding='utf-8')
print(f'Wrote {out} ({out.stat().st_size} bytes) with {len(reviews)} embedded review rows.')
